import unittest

from flowdroid_analysis import evaluate_benchmark as evaluate_flowdroid
from program_model import load_all_benchmarks
from soot_analysis import StatementRef, build_soot_pipeline
from stubdroid_analysis import evaluate_benchmark as evaluate_stubdroid, generate_library_summaries


class AnalysisStackTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.benchmarks = {program.name: program for program in load_all_benchmarks("/workspace/benchmarks")}

    def test_soot_cha_resolves_app_calls(self):
        program = self.benchmarks["InterProcedural"]
        pipeline = build_soot_pipeline(program)
        on_create = "<com.example.InterActivity: void onCreate(android.os.Bundle)>"
        obfuscate_site = StatementRef(on_create, 3)
        send_site = StatementRef(on_create, 4)
        self.assertEqual(
            pipeline.call_graph.targets_for(obfuscate_site),
            ("<com.example.InterActivity: java.lang.String obfuscate(java.lang.String)>",),
        )
        self.assertEqual(
            pipeline.call_graph.targets_for(send_site),
            ("<com.example.InterActivity: void sendData(java.lang.String)>",),
        )

    def test_flowdroid_matches_all_but_library_summary(self):
        mismatches = []
        for program in self.benchmarks.values():
            result = evaluate_flowdroid(program)
            if not result.matches_expectation:
                mismatches.append(program.name)
        self.assertEqual(mismatches, ["LibrarySummary"])

    def test_stubdroid_matches_every_benchmark(self):
        for program in self.benchmarks.values():
            result = evaluate_stubdroid(program)
            self.assertTrue(result.matches_expectation, program.name)

    def test_stubdroid_generates_container_summaries(self):
        program = self.benchmarks["LibrarySummary"]
        generation = generate_library_summaries(program)
        self.assertIn("<java.util.ArrayList: boolean add(java.lang.Object)>", generation.summaries)
        self.assertIn("<java.util.ArrayList: java.lang.Object get(int)>", generation.summaries)
        self.assertGreaterEqual(generation.flow_count, 4)


if __name__ == "__main__":
    unittest.main()
